#include "thesis_jaco_perception/multipose_alignment.hpp"
#include <ceres/ceres.h>
#include <cmath>
namespace thesis_jaco_perception { namespace {
Point3 apply(const Point3&p,const double*x){double cx=cos(x[3]),sx=sin(x[3]),cy=cos(x[4]),sy=sin(x[4]),cz=cos(x[5]),sz=sin(x[5]);return{x[0]+cz*cy*p.x+(cz*sy*sx-sz*cx)*p.y+(cz*sy*cx+sz*sx)*p.z,x[1]+sz*cy*p.x+(sz*sy*sx+cz*cx)*p.y+(sz*sy*cx-cz*sx)*p.z,x[2]-sy*p.x+cy*sx*p.y+cy*cx*p.z};}
struct Frozen {Point3 p; Capsule3 c; std::array<double,6> link_optical; bool operator()(const double*x,double*r)const{double q[6]={link_optical[0],link_optical[1],link_optical[2],link_optical[3],link_optical[4],link_optical[5]};Point3 link=apply(p,q);Point3 w=apply(link,x);r[0]=point_segment_distance(w,c.start,c.end)-c.radius;return true;}};
} MultiPoseResult MultiPoseAlignmentEstimator::estimate(const std::vector<MultiPoseCapture>&in,const std::array<double,6>&initial,const std::array<double,6>&link_optical)const{MultiPoseResult r;r.pose=initial;if(in.size()<3){r.reason="INSUFFICIENT_DISTINCT_POSES";return r;}std::vector<std::vector<Point3>>p;std::vector<std::vector<Capsule3>>c;for(auto&x:in){p.push_back(x.optical_cloud);c.push_back(x.world_capsules);}double x[6];for(int i=0;i<6;i++)x[i]=initial[i];for(auto g:std::vector<AssociationRound>{{.12,.015},{.07,.010},{.04,.005}}){auto a=associate_multipose(p,c,r.pose,g,r.rounds.size());r.rounds.push_back(a);if(a.empty()){r.reason="INSUFFICIENT_COVERAGE";return r;}ceres::Problem problem;for(auto&z:a){const auto&cap=c[z.pose_index][z.capsule_index];problem.AddResidualBlock(new ceres::NumericDiffCostFunction<Frozen,ceres::CENTRAL,1,6>(new Frozen{z.optical_point,cap,link_optical}),new ceres::HuberLoss(.02),x);}for(int i=0;i<6;i++){double d=i<3?.15:20.*M_PI/180.;problem.SetParameterLowerBound(x,i,initial[i]-d);problem.SetParameterUpperBound(x,i,initial[i]+d);}ceres::Solver::Options o;o.max_num_iterations=80;o.linear_solver_type=ceres::DENSE_QR;o.num_threads=1;ceres::Solver::Summary s;ceres::Solve(o,&problem,&s);if(!s.IsSolutionUsable()){r.reason="NOT_CONVERGED";return r;}for(int i=0;i<6;i++)r.pose[i]=x[i];}r.accepted=false;r.reason="EXPERIMENTAL_NOT_VALIDATED";return r;} }
